
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lcy_blyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lcy_blyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.023169141099117e+00, -3.941141222742124e+00, -3.826251114833652e+00, -3.667201983833323e+00, -3.450678537192292e+00, -3.162881282829273e+00, -2.793103360287816e+00, -2.339948767676080e+00, -1.818932361103208e+00, -1.265743128083458e+00, -7.436914131828388e-01, -4.658216253400332e-01, -3.859881308340933e-01, -2.864795641395301e-01, -1.597792478062747e-01, -5.078874316004807e-02, -1.343453390277947e-03, -1.017652613099182e-03, -7.438747063846171e-05, -1.749450931532742e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


